cypress_script:
describe('Buttons Page Tests', () => {
  it('should successfully click the Click Me button', () => {
    cy.visit('https://demoqa.com/buttons');
    cy.get('button#sp5Bi').click();
    cy.url().should('eq', 'https://demoqa.com/buttons');
  });
  it('should not change URL on right-clicking the Right Click Me button', () => {
    cy.visit('https://demoqa.com/buttons');
    cy.get('button#rightClickBtn').rightclick();
    cy.url().should('eq', 'https://demoqa.com/buttons');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Buttons Page Tests', () => {
  test('should successfully click the Click Me button', async ({ page }) => {
    await page.goto('https://demoqa.com/buttons');
    await page.click('button#sp5Bi');
    expect(page.url()).toBe('https://demoqa.com/buttons');
  });
  test('should not change URL on right-clicking the Right Click Me button', async ({ page }) => {
    await page.goto('https://demoqa.com/buttons');
    await page.click('button#rightClickBtn', { button: 'right' });
    expect(page.url()).toBe('https://demoqa.com/buttons');
  });
});
